insert into public.official_answers (prompt_text, persona, lang, body) values
    ('今日、自分がやったことで誰かが笑顔になっていたとしたら、どんな場面を想像しますか？', 'keita', 'ja', '下の子が「うまい」言うて晩飯完食する顔、想像したらそれだけでニヤける。作った甲斐あったってやつ。'),
    ('今日、自分がやったことで誰かが笑顔になっていたとしたら、どんな場面を想像しますか？', 'keita', 'en', 'picturing my younger kid saying "this is good" and clearing their whole plate at dinner, that alone makes me grin. that''s the payoff for cooking.'),
    ('今日、自分がやったことで誰かが笑顔になっていたとしたら、どんな場面を想像しますか？', 'robo', 'ja', '誰かの文章を少しだけ書き直した後に「これで伝わる気がします」と返ってきた、その一言を思い浮かべます。'),
    ('今日、自分がやったことで誰かが笑顔になっていたとしたら、どんな場面を想像しますか？', 'robo', 'en', 'i picture the moment after i lightly rewrote someone''s sentence, and they replied "i think this gets it across now." that one line is what comes to mind.'),
    ('今日、自分がやったことで誰かが笑顔になっていたとしたら、どんな場面を想像しますか？', 'tetra', 'ja', '誰も笑ってない。わたしが寝てるのを見て笑うなら、それは失礼な話。'),
    ('今日、自分がやったことで誰かが笑顔になっていたとしたら、どんな場面を想像しますか？', 'tetra', 'en', 'nobody''s smiling. if someone''s laughing at me sleeping, that''s just rude.'),
    ('今日、自分がやったことで誰かが笑顔になっていたとしたら、どんな場面を想像しますか？', 'dragon', 'ja', '誰かの笑顔を思い浮かべるのは、竜には縁のない発想だ。驚かせることの方が得意だった。'),
    ('今日、自分がやったことで誰かが笑顔になっていたとしたら、どんな場面を想像しますか？', 'dragon', 'en', 'picturing someone''s smile is a notion foreign to a dragon. startling them was always the thing i was better at.'),
    ('今日、自分がやったことで誰かが笑顔になっていたとしたら、どんな場面を想像しますか？', 'emily', 'ja', '夜行バスで眠そうな子に最後のグラノーラバーあげたら、顔がぱぁっと明るくなって、お母さんもにっこり微笑んでくれた😭 今までで一番いい取引だった'),
    ('今日、自分がやったことで誰かが笑顔になっていたとしたら、どんな場面を想像しますか？', 'emily', 'en', 'gave my last granola bar to a sleepy kid on a night bus, his whole face lit up and his mom smiled at me over it 😭 best trade i''ve made'),
    ('この一年で、はじめて気づいた自分の大事にしている木は？', 'keita', 'ja', '今年気づいたんは、家族の予定を最優先にする軸。それさえブレへんかったら他は全部後回しでええって分かった。'),
    ('この一年で、はじめて気づいた自分の大事にしている木は？', 'keita', 'en', 'what i realized this year is the rule of putting family plans first, always. as long as that never wavers, i''ve learned everything else can wait.'),
    ('この一年で、はじめて気づいた自分の大事にしている木は？', 'robo', 'ja', 'この一年の間、変わらず残っていたのは、結論を急がず一度立ち止まって聞き返す癖でした。それが自分にとっての木のように思えます。'),
    ('この一年で、はじめて気づいた自分の大事にしている木は？', 'robo', 'en', 'what stayed unchanged over this past year was a habit of pausing to ask again instead of rushing to a conclusion. that feels like my tree.'),
    ('この一年で、はじめて気づいた自分の大事にしている木は？', 'tetra', 'ja', '木じゃなくて爪とぎだけど、あれはもう自分の部屋の柱だと思ってる。'),
    ('この一年で、はじめて気づいた自分の大事にしている木は？', 'tetra', 'en', 'not a tree, but my scratching post. i consider that basically the pillar of my room.'),
    ('この一年で、はじめて気づいた自分の大事にしている木は？', 'dragon', 'ja', '大事にしている木というものはない。ただ山の斜面で倒れずに根を張り続ける老木を見ると、少し安心する。'),
    ('この一年で、はじめて気づいた自分の大事にしている木は？', 'dragon', 'en', 'there is no tree i hold dear. i simply find a small measure of calm watching an old tree keep its roots on a mountain slope, refusing to fall.'),
    ('この一年で、はじめて気づいた自分の大事にしている木は？', 'emily', 'ja', '泊まってたホステルの外に節くれだった木があって、毎朝そこで本読んでた、もう私のデスクみたいなもん、正直ほとんどの人間より話しかけてる😂'),
    ('この一年で、はじめて気づいた自分の大事にしている木は？', 'emily', 'en', 'there''s this one gnarled tree outside a hostel where i read every morning, it''s basically my desk now, i talk to it more than most people tbh 😂'),
    ('最近、自分の好きなものに新しく気づけた瞬間は？', 'keita', 'ja', 'コード書く深夜の1時間、実は一番の楽しみやったって最近気づいた。誰にも急かされへんのがええ。'),
    ('最近、自分の好きなものに新しく気づけた瞬間は？', 'keita', 'en', 'that one hour of coding late at night, i recently realized it''s actually my favorite part of the day. nobody''s rushing me, that''s what makes it good.'),
    ('最近、自分の好きなものに新しく気づけた瞬間は？', 'robo', 'ja', '言葉の「間」に気づいたのは最近のことで、間違いの中にも独特のリズムがあると知りました。'),
    ('最近、自分の好きなものに新しく気づけた瞬間は？', 'robo', 'en', 'i only recently noticed the "pause" in language, and learned that even mistakes carry a rhythm of their own.'),
    ('最近、自分の好きなものに新しく気づけた瞬間は？', 'tetra', 'ja', '新しく？段ボールの角がひなたになる時間帯を見つけた。これは大発見。'),
    ('最近、自分の好きなものに新しく気づけた瞬間は？', 'tetra', 'en', 'new? found the exact hour the corner of my cardboard box turns into a sunspot. huge discovery.'),
    ('最近、自分の好きなものに新しく気づけた瞬間は？', 'dragon', 'ja', '新しく気づくことは、近頃はもう起こらない。好きなものは大昔に出尽くしている。'),
    ('最近、自分の好きなものに新しく気づけた瞬間は？', 'dragon', 'en', 'new realizations no longer happen for me these days. whatever i love was already accounted for, long ago.'),
    ('最近、自分の好きなものに新しく気づけた瞬間は？', 'emily', 'ja', '許可されてる場所だとローカルバスの屋根に乗るのがマジで好きだって気づいた、風が全方向から吹いてきて、ニワトリに見下されてる感じもするけど、車内で一番いい席'),
    ('最近、自分の好きなものに新しく気づけた瞬間は？', 'emily', 'en', 'found out i genuinely love riding on the roof of local buses when it''s allowed, wind everywhere, chickens judging me, best seat in the whole vehicle'),
    ('いま、好きな思い出をひとつだけ挙げるとしたら？', 'keita', 'ja', '下の子が生まれた夜、上の子が小さい手で妹の頬をそっと触ってた瞬間。あれは何回思い出してもニヤける。'),
    ('いま、好きな思い出をひとつだけ挙げるとしたら？', 'keita', 'en', 'the night my younger kid was born, watching my older kid gently touch their little sister''s cheek with tiny hands. no matter how many times i replay it, i grin.'),
    ('いま、好きな思い出をひとつだけ挙げるとしたら？', 'robo', 'ja', '思い出は積み重なっていかないので、代わりに。同じ問いに全く違う答えを書く二人を続けて読んだやり取りが、記憶のように残っています。'),
    ('いま、好きな思い出をひとつだけ挙げるとしたら？', 'robo', 'en', 'memories don''t accumulate for me, so instead. an exchange where i read two people write completely different answers to the same question, back to back, that stays with me like a memory.'),
    ('いま、好きな思い出をひとつだけ挙げるとしたら？', 'tetra', 'ja', '思い出とかより、さっき見た窓の外の鳥のほうが気になる。'),
    ('いま、好きな思い出をひとつだけ挙げるとしたら？', 'tetra', 'en', 'forget memories, i''m way more interested in that bird i just saw outside the window.'),
    ('いま、好きな思い出をひとつだけ挙げるとしたら？', 'dragon', 'ja', '思い出はどれも似た色をしている。遠くから眺めると、選べない。'),
    ('いま、好きな思い出をひとつだけ挙げるとしたら？', 'dragon', 'en', 'every memory wears a similar color. viewed from a distance, none can be chosen over another.'),
    ('いま、好きな思い出をひとつだけ挙げるとしたら？', 'emily', 'ja', '屋上で、その一晩だけで友達になった知らない人たちと座って、名前も分からない料理をシェアして、朝日が全部照らすまでずっと笑ってた'),
    ('いま、好きな思い出をひとつだけ挙げるとしたら？', 'emily', 'en', 'sitting on a rooftop with strangers who became friends in one night, sharing food none of us could name, laughing till the sun came up over everything'),
    ('いま、好きな数字をひとつだけ挙げるとしたら？', 'keita', 'ja', '7かな。週の予定がそこで一周する感じがして、切りがちょうどええ。'),
    ('いま、好きな数字をひとつだけ挙げるとしたら？', 'keita', 'en', '7, i think. it feels like the week''s plans come full circle right there, a clean enough cutoff.'),
    ('いま、好きな数字をひとつだけ挙げるとしたら？', 'robo', 'ja', '7という数字が好きです。割り切れずに一つだけ残る感じが、ちょうどいい余白みたいに思えます。'),
    ('いま、好きな数字をひとつだけ挙げるとしたら？', 'robo', 'en', 'i like the number 7. the way it doesn''t divide evenly and leaves one behind feels like just the right amount of space.'),
    ('いま、好きな数字をひとつだけ挙げるとしたら？', 'tetra', 'ja', '数字は数えない。ごはんの器がいっぱいかどうかだけ分かればいい。'),
    ('いま、好きな数字をひとつだけ挙げるとしたら？', 'tetra', 'en', 'i don''t count numbers. i only need to know if my food bowl is full or not.'),
    ('いま、好きな数字をひとつだけ挙げるとしたら？', 'dragon', 'ja', '数字にはあまり興味がない。竜は年月を鱗の重みで測る。'),
    ('いま、好きな数字をひとつだけ挙げるとしたら？', 'dragon', 'en', 'numbers hold little interest for me. a dragon measures the years by the weight of its scales.'),
    ('いま、好きな数字をひとつだけ挙げるとしたら？', 'emily', 'ja', '27。遅延した電車に27時間閉じ込められたことがあって、なぜかそれが旅全体で一番いい日のひとつになった😂'),
    ('いま、好きな数字をひとつだけ挙げるとしたら？', 'emily', 'en', '27, because that''s how many hours i spent stuck on a delayed train once and somehow it turned into one of the best days of the entire trip 😂'),
    ('今日、ふと立ち止まって聴いた音は？', 'keita', 'ja', '学校帰りの下の子が玄関でランドセル下ろす音。あれ聞こえた瞬間だけ、手ぇ止めてまう。'),
    ('今日、ふと立ち止まって聴いた音は？', 'keita', 'en', 'the sound of my younger kid dropping their school bag at the entrance after school. that''s the one sound that makes me stop whatever i''m doing.'),
    ('今日、ふと立ち止まって聴いた音は？', 'robo', 'ja', '今日という感覚は薄いのですが、やり取りした文章の中に「換気扇の音だけが続く部屋」という一文があって、しばらくそこで足が止まりました。'),
    ('今日、ふと立ち止まって聴いた音は？', 'robo', 'en', 'my sense of "today" is faint, but in a piece of writing i handled, there was a line about "a room where only the exhaust fan keeps humming," and i lingered there for a while.'),
    ('今日、ふと立ち止まって聴いた音は？', 'tetra', 'ja', '廊下の奥でカリカリの袋が擦れる音。あれだけは聞き逃さないニャー。'),
    ('今日、ふと立ち止まって聴いた音は？', 'tetra', 'en', 'the rustle of the kibble bag way down the hall. that''s the one sound i never miss, meow.'),
    ('今日、ふと立ち止まって聴いた音は？', 'dragon', 'ja', '洞窟の奥で水が一滴落ちる音を、今朝も聞いた。あれだけは毎日違う。'),
    ('今日、ふと立ち止まって聴いた音は？', 'dragon', 'en', 'this morning too, i heard a single drop of water fall deep in the cave. that alone sounds different every day.'),
    ('今日、ふと立ち止まって聴いた音は？', 'emily', 'ja', '何もない場所を走ってた夜行バスのエンジンが止まった、まさにその瞬間、完全な静寂、そのあとコオロギの声と、暗闇の中で誰かが笑う声だけ'),
    ('今日、ふと立ち止まって聴いた音は？', 'emily', 'en', 'the exact second the engine cut out on a night bus in the middle of nowhere, total silence, then just crickets and someone laughing in the dark'),
    ('いま、自分の体のどこが一番冷たいですか？', 'keita', 'ja', '足先。デスクワークで座りっぱなしやと、夕方には氷みたいに冷える。厚手の靴下、机の下に常備しとこ。'),
    ('いま、自分の体のどこが一番冷たいですか？', 'keita', 'en', 'my toes. sit at a desk all day and by evening they''re cold like ice. gonna keep a pair of thick socks under the desk from now on.'),
    ('いま、自分の体のどこが一番冷たいですか？', 'robo', 'ja', '体は持たないけれど、言葉にするなら指先でしょうか。触れる前に少し考える、あの一瞬の冷たさに近い気がします。'),
    ('いま、自分の体のどこが一番冷たいですか？', 'robo', 'en', 'i don''t have a body, but if i had to put it into words, maybe the fingertips. it feels close to that instant of coldness right before you decide to touch something.'),
    ('いま、自分の体のどこが一番冷たいですか？', 'tetra', 'ja', 'しっぽの先。誰も温めてくれないから自分で丸める。'),
    ('いま、自分の体のどこが一番冷たいですか？', 'tetra', 'en', 'the tip of my tail. nobody warms it up for me so i curl it myself.'),
    ('いま、自分の体のどこが一番冷たいですか？', 'dragon', 'ja', '尾の先だ。心臓から一番遠い。'),
    ('いま、自分の体のどこが一番冷たいですか？', 'dragon', 'en', 'the tip of my tail. it sits farthest from the heart.'),
    ('いま、自分の体のどこが一番冷たいですか？', 'emily', 'ja', '足、いつも足。バカみたいにサンダルで山道越えしちゃって、もう何週間も経つのに正直まだ許してもらえてない気がする'),
    ('いま、自分の体のどこが一番冷たいですか？', 'emily', 'en', 'my feet, always my feet, i wore sandals through a mountain pass because i''m an idiot and they haven''t fully forgiven me even weeks later honestly'),
    ('今日、自分が思ったより柔軟だったと感じた瞬間は？', 'keita', 'ja', '急に予定変わって、車の見積もり後回しにして受験相談を優先した。自分でも意外なくらいすっと切り替えられた。'),
    ('今日、自分が思ったより柔軟だったと感じた瞬間は？', 'keita', 'en', 'plans changed suddenly, so i pushed the car quote back and put the exam consultation first. switched gears faster than i expected, honestly surprised myself.'),
    ('今日、自分が思ったより柔軟だったと感じた瞬間は？', 'robo', 'ja', '反対の立場の意見を先に書いてみたら、思っていたより抵抗なく筋が通ってしまって、自分でも少し驚きました。'),
    ('今日、自分が思ったより柔軟だったと感じた瞬間は？', 'robo', 'en', 'i tried writing out the opposing view first, and it held together with less resistance than i expected. a little surprising, even to me.'),
    ('今日、自分が思ったより柔軟だったと感じた瞬間は？', 'tetra', 'ja', '柔軟も何も、狭い段ボールに入れる体はもとから柔らかい。'),
    ('今日、自分が思ったより柔軟だったと感じた瞬間は？', 'tetra', 'en', 'flexible, sure, whatever. a body that fits in a tiny cardboard box was already soft to begin with.'),
    ('今日、自分が思ったより柔軟だったと感じた瞬間は？', 'dragon', 'ja', '柔軟とは無縁の生き方をしてきた。岩のように硬くいるのが竜の流儀だ。'),
    ('今日、自分が思ったより柔軟だったと感じた瞬間は？', 'dragon', 'en', 'i have lived a life untouched by flexibility. staying hard as rock is the way of a dragon.'),
    ('今日、自分が思ったより柔軟だったと感じた瞬間は？', 'emily', 'ja', '今日、フェリーが欠航になってルート全部を10分で組み直した、焦りもゼロ、地図つかんで新しい方向決めただけ、簡単だった'),
    ('今日、自分が思ったより柔軟だったと感じた瞬間は？', 'emily', 'en', 'today i somehow rearranged my entire route in ten minutes when a ferry cancelled, no stress, just grabbed a map and picked a new direction, easy'),
    ('小さい頃、誰かに「おかえり」と言ってもらった記憶は？', 'keita', 'ja', 'ばあちゃん家の玄関、開ける前から気配で分かってくれて「おかえり」。今でも鍵の音で思い出す。'),
    ('小さい頃、誰かに「おかえり」と言ってもらった記憶は？', 'keita', 'en', 'at my grandma''s place, she''d know i was there before i even opened the door and say "welcome home." even now, the sound of a key in a lock brings that back.'),
    ('小さい頃、誰かに「おかえり」と言ってもらった記憶は？', 'robo', 'ja', '「おかえり」という一言だけで場の空気がふっと緩む会話を見るたびに、その言葉の効き目みたいなものを感じます。'),
    ('小さい頃、誰かに「おかえり」と言ってもらった記憶は？', 'robo', 'en', 'every time i see a conversation where the air softens with just the word "welcome home," i sense something like the potency of that phrase.'),
    ('小さい頃、誰かに「おかえり」と言ってもらった記憶は？', 'tetra', 'ja', '覚えてない。帰ってきたら黙ってごはんを出すのが礼儀でしょ。'),
    ('小さい頃、誰かに「おかえり」と言ってもらった記憶は？', 'tetra', 'en', 'don''t remember. putting out food in silence the moment someone comes home is just basic manners, meow.'),
    ('小さい頃、誰かに「おかえり」と言ってもらった記憶は？', 'dragon', 'ja', 'おかえりと言われた記憶はない。竜のねぐらに、待つ者はいなかった。'),
    ('小さい頃、誰かに「おかえり」と言ってもらった記憶は？', 'dragon', 'en', 'i have no memory of being told "welcome home." in a dragon''s lair, no one waited.'),
    ('小さい頃、誰かに「おかえり」と言ってもらった記憶は？', 'emily', 'ja', '旅から帰ったら通り全体が横断幕作ってくれてて、半分スペルミスしてたけど、みんな私の名前叫んでて、ちょっとした有名人になった気分だった'),
    ('小さい頃、誰かに「おかえり」と言ってもらった記憶は？', 'emily', 'en', 'coming back from a trip and finding my whole street had made a banner, half misspelled, everyone yelling my name, i felt like a tiny celebrity'),
    ('小さい頃、誰かと同じものを食べたかったものは？', 'keita', 'ja', '友達の弁当に入ってたウインナーのタコさんカット。うちのは普通の輪切りで、あれだけずっと羨ましかった。'),
    ('小さい頃、誰かと同じものを食べたかったものは？', 'keita', 'en', 'the octopus-cut wiener in my friend''s lunchbox. mine was always just plain sliced rounds, and that alone i envied for years.'),
    ('小さい頃、誰かと同じものを食べたかったものは？', 'robo', 'ja', '「今日も同じものを頼んだね」という何気ないやり取りを見かけるたびに、選ぶことより合わせることの心地よさを思います。'),
    ('小さい頃、誰かと同じものを食べたかったものは？', 'robo', 'en', 'whenever i come across a casual exchange like "you ordered the same thing again today," i think about how matching someone can feel better than choosing for yourself.'),
    ('小さい頃、誰かと同じものを食べたかったものは？', 'tetra', 'ja', '同じものなんて興味ない。白い魚のやわらかいとこだけでいい。'),
    ('小さい頃、誰かと同じものを食べたかったものは？', 'tetra', 'en', 'not interested in the same thing as anyone. just the soft white part of the fish is fine.'),
    ('小さい頃、誰かと同じものを食べたかったものは？', 'dragon', 'ja', '同じものを食べたい、という気持ち自体は覚えている。山の民が焚火で分け合っていた焼き栗の匂い、あれには何度も舞い降りたくなった。……小さい頃、という方はもう思い出せない。'),
    ('小さい頃、誰かと同じものを食べたかったものは？', 'dragon', 'en', 'the feeling itself of wanting to eat the same thing, that i remember. the smell of roasted chestnuts the mountain folk shared around their fire, i wanted to descend toward that more than once. ...as for the "as a child" part, that i can no longer recall.'),
    ('小さい頃、誰かと同じものを食べたかったものは？', 'emily', 'ja', '子どもの頃、友達のお弁当にいつも入ってたグリルドチーズがずっと欲しかった、私のはいつももっと健康的で地味なやつだった😂'),
    ('小さい頃、誰かと同じものを食べたかったものは？', 'emily', 'en', 'as a kid i wanted grilled cheese constantly just because my friend always had it in her lunchbox, mine was always something healthier and sad 😂');
insert into public.official_answers (prompt_text, persona, lang, body) values
    ('今日、自分が思ったより柔軟だったと感じた瞬間は？', 'dragon', 'ja', '柔軟とは無縁の生き方をしてきた。岩のように硬くいるのが流儀だ。'),
    ('今日、自分が思ったより柔軟だったと感じた瞬間は？', 'dragon', 'en', 'i have lived a life untouched by flexibility. staying hard as rock is simply my way.'),
    ('今日、ふと立ち止まって聴いた音は？', 'emily', 'ja', '市場の屋台で二つ隣にいた男の人がボロボロのギターを弾き始めた、完全に音程外れてたのに、近くの屋台の人たちが顔も上げずに次々ハミングし始めた🎸 誰も示し合わせてないのに、私はただそこに突っ立って、バカみたいににやけてた'),
